  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://json.schemas.assets.semio-tech.com/os/store/composition/open/history/dictionary/schema.json",
  "title": "Store Composition Open History Dictionary",
  "$defs": {
    "Name": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9-]+$",
      "maxLength": 64
    },
    "Text": {
      "type": "string",
      "minLength": 1,
      "maxLength": 256
    },
    "Hex": {
      "type": "string",
      "pattern": "^(?:[a-f0-9]{2})+$",
      "maxLength": 4096
    },
    "Triple": {
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "items": {
        "$ref": "#/$defs/Text"
      }
    },
    "Entries": {
      "type": "integer",
      "minimum": 0,
      "maximum": 8192
    },
    "Pages": {
      "type": "integer",
      "minimum": 0,
      "maximum": 128
    },
    "OwnerRetirement": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "operation",
        "hex",
        "stage",
        "occurrence",
        "offset",
        "entries",
        "pages",
        "pendingBytes",
        "lookupBytes",
        "idBytes",
        "inputBytes",
        "retiredBytes",
        "error"
      ],
      "properties": {
        "id": {
          "$ref": "#/$defs/Name"
        },
        "operation": {
          "enum": [
            "unchanged",
            "raw-document"
          ]
        },
        "hex": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^(?:[a-f0-9]{2}){1,256}$"
        },
        "stage": {
          "enum": [
            "copy",
            "framing",
            "lookup-copy",
            "lookup-parse",
            "id-complete",
            "id-retire",
            "id-raw"
          ]
        },
        "occurrence": {
          "type": "integer",
          "minimum": 1,
          "maximum": 256
        },
        "offset": {
          "enum": [
            null,
            32
          ]
        },
        "entries": {
          "enum": [
            0,
            7
          ]
        },
        "pages": {
          "enum": [
            0,
            1
          ]
        },
        "pendingBytes": {
          "enum": [
            0,
            1
          ]
        },
        "lookupBytes": {
          "enum": [
            0,
            1
          ]
        },
        "idBytes": {
          "type": "integer",
          "minimum": 0,
          "maximum": 256
        },
        "inputBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 4096
        },
        "retiredBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 8192
        },
        "error": {
          "const": "cancelled"
        }
      }
    },
    "RecordRetirement": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "index",
        "hex",
        "cancelAfter",
        "entries",
        "pages",
        "scratchBytes",
        "inputBytes",
        "retiredBytes",
        "error"
      ],
      "properties": {
        "id": {
          "$ref": "#/$defs/Name"
        },
        "index": {
          "enum": [
            0,
            1
          ]
        },
        "hex": {
          "type": "string",
          "pattern": "^(?:[a-f0-9]{2}){1,4}$"
        },
        "cancelAfter": {
          "enum": [
            null,
            1,
            2,
            3
          ]
        },
        "entries": {
          "const": 0
        },
        "pages": {
          "enum": [
            0,
            1
          ]
        },
        "scratchBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 4
        },
        "inputBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 4096
        },
        "retiredBytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 8192
        },
        "error": {
          "enum": [
            "malformed",
            "cancelled"
          ]
        }
      }
    },
    "Lifecycle": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "at",
        "event",
        "entries",
        "pages",
        "handoffs",
        "inputBytes",
        "retiredBytes",
        "error"
      ],
      "properties": {
        "id": {
          "$ref": "#/$defs/Name"
        },
        "at": {
          "enum": [
            "begin",
            "first-entry",
            "first-delta",
            "ready",
            "witness"
          ]
        },
        "event": {
          "enum": [
            "cancel",
            "generation",
            "operation",
            "expired",
            "clock-absent",
            "none"
          ]
        },
        "entries": {
          "$ref": "#/$defs/Entries"
        },
        "pages": {
          "$ref": "#/$defs/Pages"
        },
        "handoffs": {
          "enum": [
            0,
            1
          ]
        },
        "inputBytes": {
          "const": 315
        },
        "retiredBytes": {
          "enum": [
            387,
            1411
          ]
        },
        "error": {
          "enum": [
            null,
            "cancelled",
            "stale",
            "expired"
          ]
        }
      }
    }
  }
}

